import {db,readableError} from './firebase-client.js?v=20261001-story-pages';
import {doc,onSnapshot,runTransaction,serverTimestamp} from 'https://www.gstatic.com/firebasejs/12.19.0/firebase-firestore.js';
import {fingerprint} from './song-model.js?v=20261001-story-pages';
import {defaultSettings,validateSettings,playbackSettings,directAudioURL} from './site-settings-model.js?v=20261001-story-pages';
const $=s=>document.querySelector(s),esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data=defaultSettings(),version=null,dirty=false,busy=false,stop=null,account=null,ready=false,sequence=0;
const status=(text,kind='')=>{$('#settings-status').textContent=text;$('#settings-status').className='admin-status '+kind;};
export const settingsUnsaved=()=>dirty||busy;
export function stopSettings(){sequence++;stop?.();stop=null;account=null;ready=false;dirty=false;$('#settings-fields').disabled=true;$('#save-settings').disabled=true;$('#audio-preview').pause();}
function renderTracks(){$('#track-list').innerHTML=data.tracks.length?data.tracks.map(t=>`<div class="track-item"><div><strong>${esc(t.title)}</strong><small>${t.id===data.defaultTrack?'Mặc định':'Nhạc nền'}</small></div><div class="track-actions"><button class="secondary" type="button" data-preview="${esc(t.id)}">Nghe thử</button><button class="secondary" type="button" data-default="${esc(t.id)}" ${t.id===data.defaultTrack?'disabled':''}>Chọn</button><button class="danger" type="button" data-remove="${esc(t.id)}">×</button></div></div>`).join(''):'<p class="small-note">Chưa có nhạc nền. Thêm đường dẫn đến tệp trong assets/audio/.</p>';}
function fill(){for(const [id,key] of [['banner-text','bannerText'],['audio-volume','volume']])$('#'+id).value=data[key];for(const [id,key] of [['banner-enabled','bannerEnabled'],['audio-enabled','audioEnabled'],['audio-loop','loop'],['pause-external','pauseOnExternal']])$('#'+id).checked=data[key];$('#volume-value').value=data.volume+'%';renderTracks();}
export function startSettings(user){stopSettings();const token=sequence;account=user;status('Đang tải cấu hình…');stop=onSnapshot(doc(db,'settings','site'),{includeMetadataChanges:true},snap=>{if(token!==sequence||snap.metadata.fromCache)return;ready=true;$('#settings-fields').disabled=busy;$('#save-settings').disabled=busy;if(!dirty&&!busy){try{data=playbackSettings(snap.exists()?snap.data():defaultSettings());version=snap.exists()?fingerprint(snap.data()):null;fill();status('Cấu hình đã sẵn sàng.');}catch(e){ready=false;$('#settings-fields').disabled=true;$('#save-settings').disabled=true;status(e.message,'error');}}},e=>{if(token!==sequence)return;ready=false;$('#save-settings').disabled=true;status('Chưa đọc được settings/site. Hãy áp dụng Rules mới cho cấu hình. '+readableError(e),'error');});}
$('#settings-form').addEventListener('submit',e=>e.preventDefault());$('#settings-form').addEventListener('input',()=>{dirty=true;$('#volume-value').value=$('#audio-volume').value+'%';});
$('#add-track').addEventListener('click',()=>{if(!ready||busy)return;const title=$('#audio-title').value.trim(),url=directAudioURL($('#audio-url').value);if(!title||title.length>180||!url){status('Nhập tên và đường dẫn assets/audio/ten-bai.mp3 hoặc URL âm thanh HTTPS.','error');return;}if(data.tracks.length>=8){status('Danh sách tối đa 8 bản nhạc.','error');return;}const t={id:crypto.randomUUID(),title,url};data.tracks.push(t);if(!data.defaultTrack)data.defaultTrack=t.id;dirty=true;$('#audio-title').value='';$('#audio-url').value='';renderTracks();status('Đã thêm vào cấu hình đang soạn. Bấm Lưu cấu hình để đồng bộ.');});
$('#track-list').addEventListener('click',async e=>{if(!ready||busy)return;const preview=e.target.closest('[data-preview]'),choose=e.target.closest('[data-default]'),remove=e.target.closest('[data-remove]');if(preview){const t=data.tracks.find(t=>t.id===preview.dataset.preview);if(!t)return;const a=$('#audio-preview');a.src=t.url;a.hidden=false;a.volume=Number($('#audio-volume').value)/100;try{await a.play();$('#preview-status').textContent='Đang nghe thử: '+t.title;}catch{$('#preview-status').textContent='Không phát được URL này. Kiểm tra tệp và quyền truy cập.';}}if(choose){data.defaultTrack=choose.dataset.default;dirty=true;renderTracks();}if(remove){data.tracks=data.tracks.filter(t=>t.id!==remove.dataset.remove);if(data.defaultTrack===remove.dataset.remove)data.defaultTrack=data.tracks[0]?.id||'';$('#audio-preview').pause();dirty=true;renderTracks();}});
$('#audio-preview').addEventListener('error',()=>$('#preview-status').textContent='Tệp không tải được hoặc trình duyệt không hỗ trợ định dạng.');
$('#save-settings').addEventListener('click',async()=>{if(!ready||busy||!account)return;let value;try{value=validateSettings({...data,bannerText:$('#banner-text').value,bannerEnabled:$('#banner-enabled').checked,audioEnabled:$('#audio-enabled').checked,volume:Number($('#audio-volume').value),loop:$('#audio-loop').checked,pauseOnExternal:$('#pause-external').checked});}catch(e){status(e.message,'error');return;}busy=true;$('#settings-fields').disabled=true;$('#save-settings').disabled=true;const token=sequence;try{const ref=doc(db,'settings','site');await runTransaction(db,async tx=>{const old=await tx.get(ref);if((old.exists()?fingerprint(old.data()):null)!==version)throw new Error('CONFLICT');tx.set(ref,{...value,updatedAt:serverTimestamp(),updatedBy:account.uid});});if(token!==sequence)return;dirty=false;status('Đã lưu cấu hình. Website tự nhận bản cập nhật.','success');startSettings(account);}catch(e){status(e.message==='CONFLICT'?'Cấu hình đã đổi ở nơi khác. Sao chép nội dung đang soạn rồi tải lại trang.':readableError(e),'error');}finally{busy=false;if(token===sequence){$('#settings-fields').disabled=!ready;$('#save-settings').disabled=!ready;}}});
